entries[20162] = { ["name"] = "Seal of the Crusader", ["text"] = "40 Mana\nInstant\nFills the Paladin with the spirit of a crusader for 30 sec, granting 60 melee attack power. The Paladin also attacks 40% faster, but deals less damage with each attack. Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will judge an enemy for 10 sec, increasing Holy damage taken by up to 30. Your melee strikes will refresh the spell's duration. Only one Judgement per Paladin can be active at any one time." }
entries[20164] = { ["name"] = "Seal of Justice", ["text"] = "13% of base mana\nInstant\nFills the Paladin with the spirit of justice for 30 sec, giving each melee attack a chance to stun for 2 sec. Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will judge an enemy for 10 sec, preventing them from fleeing. Your melee strikes will refresh the spell's duration. Only one Judgement per Paladin can be active at any one time." }
entries[20165] = { ["name"] = "Seal of Light", ["text"] = "110 Mana\nInstant\nFills the Paladin with divine light for 30 sec, giving each melee attack a chance to heal the Paladin for 39. Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will judge an enemy for 10 sec, granting melee attacks made against the judged enemy a chance of healing the attacker for 25. Your melee strikes will refresh the spell's duration. Only one Judgement per Paladin can be active at any one time." }
entries[20166] = { ["name"] = "Seal of Wisdom", ["text"] = "135 Mana\nInstant\nFills the Paladin with divine wisdom for 30 sec, giving each melee attack a chance to restore 50 of the Paladin's mana. Only one Seal can be active on the Paladin at any one time.\n\nUnleashing this Seal's energy will judge an enemy for 10 sec, granting attacks and spells used against the judged enemy a chance to restore 33 mana to the attacker. Your melee strikes will refresh the spell's duration. Only one Judgement per Paladin can be active at any one time." }
